// ─── Image injection ───
document.getElementById('heroBg').style.backgroundImage = "url('data:image/jpeg;base64,')";

// ─── Nav ───
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
  navbar.classList.toggle('scrolled', window.scrollY > 80);
  animateProgressBars();
}, {passive:true});

// ─── Hamburger ───
function toggleMenu(){
  const m = document.getElementById('navMenu');
  m.classList.toggle('open');
}

// ─── Apt tabs ───
function showApt(idx) {
  document.querySelectorAll('.apt-tab').forEach((b,i) => b.classList.toggle('active', i === idx));
  document.querySelectorAll('.apt-panel').forEach((p,i) => p.classList.toggle('active', i === idx));
}


// ─── Galería departamento 58,73 m² ───
let apt58Index = 0;
function showApt58(idx){
  const slides = document.querySelectorAll('#apt-4 .apt58-slide');
  const dots = document.querySelectorAll('#apt-4 .apt58-dot');
  if(!slides.length) return;
  apt58Index = (idx + slides.length) % slides.length;
  slides.forEach((s,i) => s.classList.toggle('active', i === apt58Index));
  dots.forEach((d,i) => d.classList.toggle('active', i === apt58Index));
}
function changeApt58(step){ showApt58(apt58Index + step); }

// ─── Lightbox ───
function openLightbox(src){
  document.getElementById('lightbox-img').src = src;
  document.getElementById('lightbox').classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeLightbox(){
  document.getElementById('lightbox').classList.remove('open');
  document.body.style.overflow = '';
}
document.addEventListener('keydown', e => { if(e.key==='Escape') closeLightbox(); });

// ─── Form ───
function handleSubmit(btn){
  btn.textContent = '✓ Mensaje enviado — te contactamos pronto';
  btn.style.background = '#4a7a42';
  btn.disabled = true;
  setTimeout(() => {
    btn.textContent = 'Solicitar información →';
    btn.style.background = '';
    btn.disabled = false;
  }, 4000);
}

// ─── Reveal on scroll ───
const revealEls = document.querySelectorAll('.reveal');
function checkReveal(){
  revealEls.forEach(el => {
    if(el.getBoundingClientRect().top < window.innerHeight * 0.89)
      el.classList.add('visible');
  });
}
window.addEventListener('scroll', checkReveal, {passive:true});
window.addEventListener('load', () => {
  document.getElementById('heroBg').classList.add('ready');
  checkReveal();
});
checkReveal();

// ─── Progress bars ───
let progressDone = false;
function animateProgressBars(){
  if(progressDone) return;
  const obraSection = document.getElementById('obra');
  if(!obraSection) return;
  const rect = obraSection.getBoundingClientRect();
  if(rect.top < window.innerHeight * 0.8){
    document.querySelectorAll('.progress-fill').forEach(el => el.classList.add('animated'));
    progressDone = true;
  }
}

let essentiaSpaIndex = 0;
function spaGo(i){
  const slides=document.querySelectorAll('#amenidades .spa-slide');
  const dots=document.querySelectorAll('#amenidades .spa-dot');
  if(!slides.length) return;
  essentiaSpaIndex=(i+slides.length)%slides.length;
  slides.forEach((el,n)=>el.classList.toggle('active',n===essentiaSpaIndex));
  dots.forEach((el,n)=>el.classList.toggle('active',n===essentiaSpaIndex));
}
function spaMove(delta){ spaGo(essentiaSpaIndex+delta); }
